-- Convert project "fiets123" to activities, using: V01 - Stakeholders per fase.xlsx
-- Generated by scripts/template-to-activities.ts on 2026-11-10T11:14:28.988Z
-- 53 activities, 206 stakeholder links.
-- Runs in one transaction; refuses to run if the project already has activities.

BEGIN;

CREATE TEMP TABLE tpl ON COMMIT DROP AS
SELECT id FROM projects WHERE name = 'fiets123' AND deleted_at IS NULL;

DO $$
BEGIN
  IF (SELECT count(*) FROM tpl) <> 1 THEN
    RAISE EXCEPTION 'Project "%" niet (of meer dan eens) gevonden. Er is niets aangepast.', 'fiets123';
  END IF;
  IF EXISTS (SELECT 1 FROM activities a JOIN tpl ON tpl.id = a.project_id WHERE a.deleted_at IS NULL) THEN
    RAISE EXCEPTION 'Dit project heeft al activiteiten. Er is niets aangepast.';
  END IF;
END $$;

CREATE TEMP TABLE import_ctx ON COMMIT DROP AS
SELECT gen_random_uuid() AS batch_id,
       (SELECT id FROM users WHERE role = 'admin' AND status = 'active' ORDER BY created_at LIMIT 1) AS actor_id;

CREATE TEMP TABLE act_import (phase_name text, sort int, seq int, number text, name text, description text, result text) ON COMMIT DROP;

CREATE TEMP TABLE member_import (phase_name text, number text, stakeholder_name text, role stakeholder_role, sort int) ON COMMIT DROP;

-- 1. Activities
WITH ins AS (
  SELECT tpl.id, f.id, ai.number, ai.name, ai.description, ai.result, ai.sort,
         now() + ai.seq * interval '1 millisecond', now() + ai.seq * interval '1 millisecond'
  FROM act_import ai
  CROSS JOIN tpl
  JOIN phases f ON f.project_id = tpl.id AND f.name = ai.phase_name AND f.deleted_at IS NULL
  RETURNING *
)
SELECT ins.project_id, 'activity', ins.id, 'create', NULL, jsonb_build_object(
    'id', ins.id, 'projectId', ins.project_id, 'phaseId', ins.phase_id, 'number', ins.number, 'name', ins.name,
    'description', ins.description, 'result', ins.result, 'status', ins.status,
    'statusChangedBy', ins.status_changed_by, 'statusChangedAt', CASE WHEN ins.status_changed_at IS NULL THEN NULL ELSE to_char(ins.status_changed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END, 'sortOrder', ins.sort_order,
    'version', ins.version, 'deletedAt', CASE WHEN ins.deleted_at IS NULL THEN NULL ELSE to_char(ins.deleted_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END, 'createdAt', CASE WHEN ins.created_at IS NULL THEN NULL ELSE to_char(ins.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END, 'updatedAt', CASE WHEN ins.updated_at IS NULL THEN NULL ELSE to_char(ins.updated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END), c.actor_id, c.batch_id, 'Omgezet naar activiteiten (bron: V01 - Stakeholders per fase.xlsx)'
FROM ins CROSS JOIN import_ctx c ORDER BY ins.created_at;

DO $$
BEGIN
  IF (SELECT count(*) FROM activities a JOIN tpl ON tpl.id = a.project_id WHERE a.deleted_at IS NULL)
     <> (SELECT count(*) FROM act_import) THEN
    RAISE EXCEPTION 'Niet alle fases uit de Excel bestaan in het project. Er is niets aangepast.';
  END IF;
END $$;

-- 2. One stakeholder row per party per activity, copied from the old phase-level row (if any)
CREATE TEMP TABLE member_map ON COMMIT DROP AS
SELECT gen_random_uuid() AS new_id, src.id AS src_id, a.id AS activity_id, a.phase_id, mi.role, mi.sort,
       mi.stakeholder_name, a.created_at
FROM member_import mi
CROSS JOIN tpl
JOIN phases f ON f.project_id = tpl.id AND f.name = mi.phase_name AND f.deleted_at IS NULL
JOIN activities a ON a.phase_id = f.id AND a.number = mi.number AND a.deleted_at IS NULL
LEFT JOIN LATERAL (
  SELECT s.id FROM stakeholders s
  WHERE s.phase_id = f.id AND s.activity_id IS NULL AND s.deleted_at IS NULL AND s.name = mi.stakeholder_name
  ORDER BY s.sort_order LIMIT 1
) src ON true;

  id, project_id, phase_id, activity_id, role, sort_order, name, contact_person, email, phone, description,
  deadline, activities, interests, status, status_changed_by, status_changed_at, created_at, updated_at)
SELECT mm.new_id, tpl.id, mm.phase_id, mm.activity_id, mm.role, mm.sort, mm.stakeholder_name,
       coalesce(s.contact_person, ''), coalesce(s.email, ''), coalesce(s.phone, ''),
       -- Drop the generated "Leidend bij: … / Betrokken bij: …" summary from the first import.
       CASE WHEN s.description ~ '^(Leidend bij|Betrokken bij):' THEN '' ELSE coalesce(s.description, '') END,
       s.deadline,
       -- Drop the generated per-step to-do list: it is now the activity's description and result.
       CASE WHEN s.activities ~ '^[0-9]+\.[0-9]+ .*\((leidend|betrokken)\)' THEN '' ELSE coalesce(s.activities, '') END,
       coalesce(s.interests, ''), coalesce(s.status, 'not_started'), s.status_changed_by, s.status_changed_at,
       mm.created_at + mm.sort * interval '1 microsecond', now()
FROM member_map mm
CROSS JOIN tpl
LEFT JOIN stakeholders s ON s.id = mm.src_id;

SELECT s.project_id, 'stakeholder', s.id, 'create', NULL, jsonb_build_object(
    'id', s.id, 'projectId', s.project_id, 'phaseId', s.phase_id, 'activityId', s.activity_id, 'role', s.role,
    'sortOrder', s.sort_order, 'name', s.name, 'contactPerson', s.contact_person, 'email', s.email,
    'phone', s.phone, 'description', s.description, 'deadline', s.deadline, 'activities', s.activities,
    'interests', s.interests, 'status', s.status, 'statusChangedBy', s.status_changed_by,
    'statusChangedAt', CASE WHEN s.status_changed_at IS NULL THEN NULL ELSE to_char(s.status_changed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END,
    'version', s.version, 'deletedAt', CASE WHEN s.deleted_at IS NULL THEN NULL ELSE to_char(s.deleted_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END, 'createdAt', CASE WHEN s.created_at IS NULL THEN NULL ELSE to_char(s.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END, 'updatedAt', CASE WHEN s.updated_at IS NULL THEN NULL ELSE to_char(s.updated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END), c.actor_id, c.batch_id, 'Omgezet naar activiteiten (bron: V01 - Stakeholders per fase.xlsx)'
FROM stakeholders s JOIN member_map mm ON mm.new_id = s.id CROSS JOIN import_ctx c ORDER BY s.created_at;

-- 3. Documentation and comments go along with every copy
WITH ins AS (
  SELECT l.project_id, mm.new_id, l.title, l.url, l.description, l.created_by, l.created_at, now()
  FROM member_map mm JOIN doc_links l ON l.stakeholder_id = mm.src_id AND l.deleted_at IS NULL
  RETURNING *
)
SELECT ins.project_id, 'doc_link', ins.id, 'create', NULL, jsonb_build_object(
    'id', ins.id, 'projectId', ins.project_id, 'stakeholderId', ins.stakeholder_id, 'title', ins.title, 'url', ins.url,
    'description', ins.description, 'createdBy', ins.created_by,
    'version', ins.version, 'deletedAt', CASE WHEN ins.deleted_at IS NULL THEN NULL ELSE to_char(ins.deleted_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END, 'createdAt', CASE WHEN ins.created_at IS NULL THEN NULL ELSE to_char(ins.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END, 'updatedAt', CASE WHEN ins.updated_at IS NULL THEN NULL ELSE to_char(ins.updated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END), c.actor_id, c.batch_id, 'Omgezet naar activiteiten (bron: V01 - Stakeholders per fase.xlsx)'
FROM ins CROSS JOIN import_ctx c;

WITH ins AS (
  SELECT d.project_id, mm.new_id, d.blob_id, d.filename, d.mime_type, d.size, d.created_by, d.created_at, now()
  FROM member_map mm JOIN doc_files d ON d.stakeholder_id = mm.src_id AND d.deleted_at IS NULL
  RETURNING *
)
SELECT ins.project_id, 'doc_file', ins.id, 'create', NULL, jsonb_build_object(
    'id', ins.id, 'projectId', ins.project_id, 'stakeholderId', ins.stakeholder_id, 'blobId', ins.blob_id,
    'filename', ins.filename, 'mimeType', ins.mime_type, 'size', ins.size, 'createdBy', ins.created_by,
    'version', ins.version, 'deletedAt', CASE WHEN ins.deleted_at IS NULL THEN NULL ELSE to_char(ins.deleted_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END, 'createdAt', CASE WHEN ins.created_at IS NULL THEN NULL ELSE to_char(ins.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END, 'updatedAt', CASE WHEN ins.updated_at IS NULL THEN NULL ELSE to_char(ins.updated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END), c.actor_id, c.batch_id, 'Omgezet naar activiteiten (bron: V01 - Stakeholders per fase.xlsx)'
FROM ins CROSS JOIN import_ctx c;

WITH ins AS (
  SELECT k.project_id, NULL, mm.new_id, k.author_id, k.body, k.labels, k.edited_at, k.created_at, now()
  FROM member_map mm JOIN comments k ON k.stakeholder_id = mm.src_id AND k.deleted_at IS NULL
  RETURNING *
)
SELECT ins.project_id, 'comment', ins.id, 'create', NULL, jsonb_build_object(
    'id', ins.id, 'projectId', ins.project_id, 'phaseId', ins.phase_id, 'stakeholderId', ins.stakeholder_id,
    'authorId', ins.author_id, 'body', ins.body, 'labels', to_jsonb(ins.labels), 'editedAt', CASE WHEN ins.edited_at IS NULL THEN NULL ELSE to_char(ins.edited_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END,
    'version', ins.version, 'deletedAt', CASE WHEN ins.deleted_at IS NULL THEN NULL ELSE to_char(ins.deleted_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END, 'createdAt', CASE WHEN ins.created_at IS NULL THEN NULL ELSE to_char(ins.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END, 'updatedAt', CASE WHEN ins.updated_at IS NULL THEN NULL ELSE to_char(ins.updated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END), c.actor_id, c.batch_id, 'Omgezet naar activiteiten (bron: V01 - Stakeholders per fase.xlsx)'
FROM ins CROSS JOIN import_ctx c;

-- 4. Soft-delete the converted phase-level rows (they can be restored via Geschiedenis)
CREATE TEMP TABLE old_rows ON COMMIT DROP AS
SELECT s.id, jsonb_build_object(
    'id', s.id, 'projectId', s.project_id, 'phaseId', s.phase_id, 'activityId', s.activity_id, 'role', s.role,
    'sortOrder', s.sort_order, 'name', s.name, 'contactPerson', s.contact_person, 'email', s.email,
    'phone', s.phone, 'description', s.description, 'deadline', s.deadline, 'activities', s.activities,
    'interests', s.interests, 'status', s.status, 'statusChangedBy', s.status_changed_by,
    'statusChangedAt', CASE WHEN s.status_changed_at IS NULL THEN NULL ELSE to_char(s.status_changed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END,
    'version', s.version, 'deletedAt', CASE WHEN s.deleted_at IS NULL THEN NULL ELSE to_char(s.deleted_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END, 'createdAt', CASE WHEN s.created_at IS NULL THEN NULL ELSE to_char(s.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END, 'updatedAt', CASE WHEN s.updated_at IS NULL THEN NULL ELSE to_char(s.updated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END) AS before
FROM stakeholders s
WHERE s.id IN (SELECT src_id FROM member_map WHERE src_id IS NOT NULL);

UPDATE stakeholders s
SET deleted_at = now(), version = s.version + 1, updated_at = now()
WHERE s.id IN (SELECT id FROM old_rows);

SELECT s.project_id, 'stakeholder', s.id, 'delete', o.before, jsonb_build_object(
    'id', s.id, 'projectId', s.project_id, 'phaseId', s.phase_id, 'activityId', s.activity_id, 'role', s.role,
    'sortOrder', s.sort_order, 'name', s.name, 'contactPerson', s.contact_person, 'email', s.email,
    'phone', s.phone, 'description', s.description, 'deadline', s.deadline, 'activities', s.activities,
    'interests', s.interests, 'status', s.status, 'statusChangedBy', s.status_changed_by,
    'statusChangedAt', CASE WHEN s.status_changed_at IS NULL THEN NULL ELSE to_char(s.status_changed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END,
    'version', s.version, 'deletedAt', CASE WHEN s.deleted_at IS NULL THEN NULL ELSE to_char(s.deleted_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END, 'createdAt', CASE WHEN s.created_at IS NULL THEN NULL ELSE to_char(s.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END, 'updatedAt', CASE WHEN s.updated_at IS NULL THEN NULL ELSE to_char(s.updated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END), c.actor_id, c.batch_id, 'Omgezet naar activiteiten (bron: V01 - Stakeholders per fase.xlsx)'
FROM stakeholders s JOIN old_rows o ON o.id = s.id CROSS JOIN import_ctx c;

DO $$
DECLARE a int; s int; n int; o int;
BEGIN
  SELECT count(*) INTO a FROM act_import;
  SELECT count(*) INTO s FROM member_map;
  SELECT count(*) INTO n FROM member_map WHERE src_id IS NULL;
  SELECT count(*) INTO o FROM old_rows;
  RAISE NOTICE 'Klaar: % activiteiten, % stakeholderregels (% nieuw zonder bron), % oude regels vervangen.', a, s, n, o;
END $$;

COMMIT;
