INSERT INTO act_import VALUES
  ('Initiatief en locatiekeuze', 1, 0, '1.1', 'Ambitie en projectopdracht bepalen', 'Wat wil de ontwikkelaar bereiken (aantal woningen, doelgroep, budget) en is de ontwikkeling interessant?', 'Startnotitie met ambities'),
  ('Initiatief en locatiekeuze', 2, 1, '1.2', 'Planologische mogelijkheden controleren', 'Mag hier gewoond worden volgens omgevingsplan, provinciale verordening en landelijke regels?', 'Overzicht planologische kaders'),
  ('Initiatief en locatiekeuze', 3, 2, '1.3', 'Grondpositie controleren', 'Wie is eigenaar, is de grond te koop, welke rechten rusten erop en wat is het huidige (agrarische) gebruik?', 'Overzicht eigendom en beschikbaarheid'),
  ('Initiatief en locatiekeuze', 4, 3, '1.4', 'Woningbehoefte en doelgroepen verkennen', 'Welke woningen en doelgroepen zijn nodig (sociale huur, betaalbaar, ouderen)?', 'Eerste woningbehoefte'),
  ('Initiatief en locatiekeuze', 5, 4, '1.5', 'Omgeving en eerste draagvlak verkennen', 'Welke zorgen en wensen leven er in de buurt en bij natuur-, landbouw- en maatschappelijke organisaties? Hoe wordt participatie georganiseerd?', 'Participatieaanpak en eerste aandachtspunten'),
  ('Initiatief en locatiekeuze', 6, 5, '1.6', 'Financiële interesse peilen', 'Is er op hoofdlijnen interesse van financiers, beleggers en corporaties?', 'Indicatie financiële interesse'),
  ('Initiatief en locatiekeuze', 7, 6, '1.7', 'Locatiekeuze vastleggen', 'Gaan we verder met deze locatie (go/no-go)?', 'Besluit over locatie'),
  ('Onderzoek en haalbaarheid', 1, 7, '2.1', 'Grond controleren', 'Is de bodem schoon genoeg voor wonen, tuinen en speelplekken? Is sanering nodig?', 'Bodemonderzoek'),
  ('Onderzoek en haalbaarheid', 2, 8, '2.2', 'Ondergrond en draagkracht controleren', 'Kan de bodem woningen en wegen dragen? Welke fundering en ophoging zijn nodig?', 'Geotechnisch advies'),
  ('Onderzoek en haalbaarheid', 3, 9, '2.3', 'Waterafvoer en waterhuishouding controleren', 'Hoeveel waterberging is nodig, hoe wordt regenwater en afvalwater afgevoerd en wat zijn de waterpeilen?', 'Watertoets en waterplan op hoofdlijnen'),
  ('Onderzoek en haalbaarheid', 4, 10, '2.4', 'Klimaatrisico''s controleren', 'Waar ontstaat wateroverlast, hittestress of droogte?', 'Klimaatstresstest'),
  ('Onderzoek en haalbaarheid', 5, 11, '2.5', 'Natuur en beschermde soorten controleren', 'Zijn er beschermde planten en dieren of Natura 2000-gebieden in de buurt?', 'Quickscan flora en fauna'),
  ('Onderzoek en haalbaarheid', 6, 12, '2.6', 'Milieu en gezondheid controleren', 'Wat zijn geluid, luchtkwaliteit, geur en externe veiligheid op de locatie, ook langs snelweg en spoor? Wat betekent dat voor de gezondheid?', 'Milieuonderzoeken en gezondheidsadvies'),
  ('Onderzoek en haalbaarheid', 7, 13, '2.7', 'Nutsvoorzieningen en netcapaciteit controleren', 'Is er genoeg capaciteit voor stroom, drinkwater, riolering, warmte en telecom? Welke kabels en leidingen liggen er al?', 'Overzicht capaciteit en bestaande ondergrond'),
  ('Onderzoek en haalbaarheid', 8, 14, '2.8', 'Bereikbaarheid en verkeer controleren', 'Hoe sluit de wijk aan op wegen, fietsroutes en OV? Hoeveel verkeer en parkeren levert de wijk op?', 'Verkeers- en mobiliteitsonderzoek'),
  ('Onderzoek en haalbaarheid', 9, 15, '2.9', 'Woningprogramma en doelgroepen toetsen', 'Passen de woningtypen bij de doelgroepen en bij de mogelijkheden van corporaties?', 'Concept woningprogramma'),
  ('Onderzoek en haalbaarheid', 10, 16, '2.10', 'Juridische haalbaarheid controleren', 'Welke procedures en vergunningen zijn nodig en zijn er juridische belemmeringen?', 'Juridische scan en procedureplanning'),
  ('Onderzoek en haalbaarheid', 11, 17, '2.11', 'Financiële haalbaarheid controleren', 'Wegen kosten, opbrengsten, subsidies en belastingen tegen elkaar op? Is het project financierbaar?', 'Eerste grondexploitatie en financieringsbeeld'),
  ('Onderzoek en haalbaarheid', 12, 18, '2.12', 'Reacties uit de omgeving ophalen', 'Welke knelpunten zien inwoners en lokale organisaties?', 'Verslag participatie'),
  ('Onderzoek en haalbaarheid', 13, 19, '2.13', 'Haalbaarheid beoordelen', 'Is de locatie op alle onderdelen haalbaar (go/no-go)?', 'Haalbaarheidsbesluit'),
  ('Programma van Eisen en conceptontwikkeling', 1, 20, '3.1', 'Uitgangspunten en programma van eisen vaststellen', 'Welke eisen gelden voor woningen, doelgroepen, betaalbaarheid en voorzieningen?', 'Programma van eisen'),
  ('Programma van Eisen en conceptontwikkeling', 2, 21, '3.2', 'Woonwensen en doelgroepen ophalen', 'Wat vinden toekomstige bewoners, huurders en zorgvragers belangrijk?', 'Overzicht woonwensen'),
  ('Programma van Eisen en conceptontwikkeling', 3, 22, '3.3', 'Stedenbouwkundig concept maken', 'Waar komen woningen, straten, groen en openbare ruimte?', 'Stedenbouwkundig concept'),
  ('Programma van Eisen en conceptontwikkeling', 4, 23, '3.4', 'Mobiliteit en parkeren inpassen', 'Past het concept bij het mobiliteitsbeleid en zijn wegen, routes en parkeren goed ingepast?', 'Verkeers- en parkeerconcept'),
  ('Programma van Eisen en conceptontwikkeling', 5, 24, '3.5', 'Groen en gezonde leefomgeving inpassen', 'Is er voldoende groen, speelruimte en ruimte om te bewegen?', 'Groenconcept'),
  ('Programma van Eisen en conceptontwikkeling', 6, 25, '3.6', 'Toegankelijkheid controleren', 'Zijn woningen, looproutes en voorzieningen bruikbaar voor mensen met een beperking?', 'Toegankelijkheidstoets'),
  ('Programma van Eisen en conceptontwikkeling', 7, 26, '3.7', 'Eerste woningontwerp maken', 'Hoe zien de woningen en gebouwen eruit en voldoen ze aan de kwaliteitseisen?', 'Schetsontwerp woningen'),
  ('Programma van Eisen en conceptontwikkeling', 8, 27, '3.8', 'Beheerbaarheid controleren', 'Is de openbare ruimte en zijn de gemeenschappelijke ruimtes later goed te onderhouden?', 'Beheeradvies'),
  ('Programma van Eisen en conceptontwikkeling', 9, 28, '3.9', 'Uitvoerbaarheid controleren', 'Is het concept te bouwen en welke bouwmethode past?', 'Advies uitvoerbaarheid'),
  ('Programma van Eisen en conceptontwikkeling', 10, 29, '3.10', 'Concept voorleggen aan de omgeving', 'Wat vinden buurt, wijkraad en organisaties van het concept?', 'Reacties op concept'),
  ('Programma van Eisen en conceptontwikkeling', 11, 30, '3.11', 'Concept vaststellen', 'Welk concept wordt verder uitgewerkt?', 'Vastgesteld concept en PvE'),
  ('Planuitwerking en technische afstemming', 1, 31, '4.1', 'Woningen uitwerken tot bouwtekeningen', 'Zijn de woningen uitgewerkt en passen ze nog bij het stedenbouwkundig plan en het woningprogramma?', 'Definitief ontwerp woningen'),
  ('Planuitwerking en technische afstemming', 2, 32, '4.2', 'Constructie en fundering controleren', 'Is het gebouw constructief veilig en past de fundering bij de bodem?', 'Constructieberekeningen'),
  ('Planuitwerking en technische afstemming', 3, 33, '4.3', 'Wegen en openbare ruimte uitwerken', 'Zijn wegen, stoepen en openbare ruimte technisch uitgewerkt en goed te beheren?', 'Inrichtingsplan openbare ruimte'),
  ('Planuitwerking en technische afstemming', 4, 34, '4.4', 'Waterafvoer en riolering uitwerken', 'Zijn riolering, watergangen en waterberging uitgewerkt en klimaatbestendig?', 'Rioleringsplan en waterplan'),
  ('Planuitwerking en technische afstemming', 5, 35, '4.5', 'Kabels, leidingen en aansluitingen afstemmen', 'Passen alle kabels en leidingen in de ondergrond zonder conflicten?', 'Kabels- en leidingenplan'),
  ('Planuitwerking en technische afstemming', 6, 36, '4.6', 'Energie- en warmtevoorziening uitwerken', 'Is de warmtevoorziening technisch uitgewerkt en is er netcapaciteit gereserveerd?', 'Energieplan'),
  ('Planuitwerking en technische afstemming', 7, 37, '4.7', 'Bereikbaarheid voor hulpdiensten, afval en bezorging controleren', 'Kunnen brandweer, ambulance, vuilniswagen en bezorgers elke woning bereiken?', 'Bereikbaarheidstoets'),
  ('Planuitwerking en technische afstemming', 8, 38, '4.8', 'Verkeer, OV en parkeren uitwerken', 'Zijn routes, haltes, parkeerplaatsen en aansluitingen op rijks- en provinciale wegen uitgewerkt?', 'Verkeersplan'),
  ('Planuitwerking en technische afstemming', 9, 39, '4.9', 'Toegankelijkheid controleren', 'Voldoen de uitgewerkte plannen aan de toegankelijkheidseisen?', 'Toegankelijkheidstoets'),
  ('Planuitwerking en technische afstemming', 10, 40, '4.10', 'Uitvoerbaarheid en bouwlogistiek controleren', 'Is het plan te bouwen en hoe verloopt het bouwverkeer langs bestaande routes en de buurt?', 'Bouwmethode en BLVC-plan'),
  ('Planuitwerking en technische afstemming', 11, 41, '4.11', 'Beheer en onderhoud controleren', 'Zijn openbare ruimte, gebouwen en gemeenschappelijke ruimtes goed te onderhouden?', 'Beheerplan op hoofdlijnen'),
  ('Planuitwerking en technische afstemming', 12, 42, '4.12', 'Vergunningen en kwaliteit voorbereiden', 'Kloppen de plannen juridisch en voldoen ze aan de kwaliteitseisen?', 'Vergunningaanvraag en borgingsplan'),
  ('Planuitwerking en technische afstemming', 13, 43, '4.13', 'Omgeving informeren over de uitwerking', 'Wat is er met eerdere reacties gedaan en wat merkt de buurt van de bouw?', 'Terugkoppeling aan omgeving'),
  ('Planuitwerking en technische afstemming', 14, 44, '4.14', 'Technisch plan vaststellen', 'Is het plan klaar voor de financiële toets?', 'Vastgesteld technisch plan'),
  ('Financiële onderbouwing, toetsing en overdracht', 1, 45, '5.1', 'Kosten en opbrengsten controleren', 'Kloppen bouwkosten, opbrengsten, subsidies en belastingen?', 'Definitieve grondexploitatie en begroting'),
  ('Financiële onderbouwing, toetsing en overdracht', 2, 46, '5.2', 'Financiering rond maken', 'Willen financiers, banken en corporaties investeren en onder welke voorwaarden?', 'Financieringsafspraken'),
  ('Financiële onderbouwing, toetsing en overdracht', 3, 47, '5.3', 'Woningprogramma en afname vastleggen', 'Welke woningen neemt de corporatie af en past de verdeling bij het gemeentelijk beleid?', 'Afnameafspraken woningen'),
  ('Financiële onderbouwing, toetsing en overdracht', 4, 48, '5.4', 'Contracten en juridische afspraken controleren', 'Zijn contracten, vergunningen, risico''s en garanties goed geregeld?', 'Getoetste contracten'),
  ('Financiële onderbouwing, toetsing en overdracht', 5, 49, '5.5', 'Grondoverdracht regelen', 'Wordt de grond juridisch en fiscaal correct overgedragen en ingeschreven?', 'Akte van levering en kadastrale inschrijving'),
  ('Financiële onderbouwing, toetsing en overdracht', 6, 50, '5.6', 'Beheer na oplevering afspreken', 'Wie beheert openbare ruimte, gebouwen, afvalinzameling en bezorgvoorzieningen na oplevering?', 'Beheer- en overdrachtsafspraken'),
  ('Financiële onderbouwing, toetsing en overdracht', 7, 51, '5.7', 'Omgeving informeren en participatie vastleggen', 'Zijn buurt en toekomstige bewoners geïnformeerd en is de participatie vastgelegd?', 'Participatieverslag'),
  ('Financiële onderbouwing, toetsing en overdracht', 8, 52, '5.8', 'Plan overdragen aan projectontwikkelaar', 'Sluit het plan aan op de oorspronkelijke doelen en is alles klaar voor de overdracht?', 'Overdrachtsdossier');
